// Live permissions cache — loaded from Supabase on login
let _permissions = { ...DEFAULT_PERMISSIONS };
async function loadPermissions() {
  try {
    const rows = await sbFetch("permissions?select=user_id,can_delete,can_see_dollars,can_backup,can_submit_jobs,can_edit_jobs,can_view_contacts,can_view_docs,visible_tabs,visible_hub_apps");
    if (rows?.length) {
      const map = {};
      rows.forEach(r => {
        map[r.user_id] = {
          canDelete:       r.can_delete,
          canSeeDollars:   r.can_see_dollars,
          canBackup:       r.can_backup,
          canSubmitJobs:   r.can_submit_jobs,
          canEditJobs:     r.can_edit_jobs,
          canViewContacts: r.can_view_contacts,
          canViewDocs:     r.can_view_docs,
          visibleTabIds:   Array.isArray(r.visible_tabs) ? r.visible_tabs : null,
          visibleHubAppIds: Array.isArray(r.visible_hub_apps) ? r.visible_hub_apps : null,
        };
      });
      _permissions = { ...DEFAULT_PERMISSIONS, ...map };
    }
  } catch {}
}
async function savePermission(userId, perms, updatedBy) {
  await sbFetch(`permissions?user_id=eq.${userId}`, {
    method: "PATCH",
    body: JSON.stringify({
      can_delete:        perms.canDelete,
      can_see_dollars:   perms.canSeeDollars,
      can_backup:        perms.canBackup,
      can_submit_jobs:   perms.canSubmitJobs,
      can_edit_jobs:     perms.canEditJobs,
      can_view_contacts: perms.canViewContacts,
      can_view_docs:     perms.canViewDocs,
      visible_tabs:      Array.isArray(perms.visibleTabIds) ? perms.visibleTabIds : null,
      visible_hub_apps:  Array.isArray(perms.visibleHubAppIds) ? perms.visibleHubAppIds : null,
      updated_by: updatedBy,
      updated_at: new Date().toISOString(),
    }),
  });
  _permissions[userId] = perms;
}

// ─── Profile Pictures ─────────────────────────────────────────────────────────
const _profilePics = {};
async function loadProfilePics() {
  try {
    const rows = await sbFetch("user_profiles?select=user_id,avatar_url");
    (rows || []).forEach(r => {
      if (r.avatar_url) _profilePics[r.user_id] = r.avatar_url;
    });
    // Notify any mounted ProfileAvatar components
    window.dispatchEvent(new CustomEvent("profilePicsLoaded"));
  } catch {}
}
async function saveProfilePic(userId, dataUrl) {
  try {
    const existing = await sbFetch(`user_profiles?user_id=eq.${userId}&select=user_id`);
    if (existing?.length) {
      await sbFetch(`user_profiles?user_id=eq.${userId}`, { method: "PATCH", body: JSON.stringify({ avatar_url: dataUrl, updated_at: new Date().toISOString() }) });
    } else {
      await sbFetch("user_profiles", { method: "POST", body: JSON.stringify({ user_id: userId, avatar_url: dataUrl, updated_at: new Date().toISOString() }) });
    }
    _profilePics[userId] = dataUrl;
    window.dispatchEvent(new CustomEvent("profilePicsLoaded"));
  } catch(e) { throw e; }
}

// Contact info (cell phone + email) captured on first login, alongside the
// avatar in the same user_profiles table.
async function fetchContactInfo(userId) {
  const rows = await sbFetch(`user_profiles?user_id=eq.${userId}&select=user_id,cell_phone,email`);
  return rows?.[0] || null;
}
async function saveContactInfo(userId, cellPhone, email) {
  const existing = await sbFetch(`user_profiles?user_id=eq.${userId}&select=user_id`);
  const patch = { cell_phone: cellPhone || null, email: email || null, updated_at: new Date().toISOString() };
  if (existing?.length) {
    await sbFetch(`user_profiles?user_id=eq.${userId}`, { method: "PATCH", body: JSON.stringify(patch) });
  } else {
    await sbFetch("user_profiles", { method: "POST", body: JSON.stringify({ user_id: userId, ...patch }) });
  }
}
function getProfilePic(userId) { return _profilePics[userId] || null; }

function getPerms(user) { return _permissions[user?.id] || DEFAULT_PERMISSIONS[user?.id] || {}; }
function canDelete(user)       { return !!getPerms(user).canDelete; }
function canSeeDollars(user)   { return !!getPerms(user).canSeeDollars; }
function canBackup(user)       { return !!getPerms(user).canBackup; }
function canSubmitJobs(user)   { return !!getPerms(user).canSubmitJobs; }
function canEditJobs(user)     { return !!getPerms(user).canEditJobs; }
function canViewContacts(user) { return !!getPerms(user).canViewContacts; }
function canViewDocs(user)     { return !!getPerms(user).canViewDocs; }
function canAdmin(user)        { return CAN_ADMIN.includes(user?.id); }

