// ─── Icon Badge — circular icon container matching the S&H Services business
// card style (navy outline circle, navy or white fill depending on context).
// Wraps any emoji or SVG icon so it visually matches the card's water-drop/
// flame/virus/storm/house/hammer icon treatment throughout the app.
function IconBadge({ children, size = 32, filled = false, color = BRAND.navy, onDark = false }) {
  const iconColor = filled ? BRAND.white : (onDark ? "rgba(255,255,255,0.9)" : color);
  return (
    <span style={{
      display: "inline-flex", alignItems: "center", justifyContent: "center",
      width: size, height: size, borderRadius: "50%", flexShrink: 0,
      background: filled ? color : (onDark ? "rgba(255,255,255,0.12)" : BRAND.white),
      border: `2px solid ${onDark ? "rgba(255,255,255,0.9)" : color}`,
      color: iconColor,
      fontSize: size * 0.5, lineHeight: 1,
    }}>
      {children}
    </span>
  );
}

// ─── Tab nav button — circular card-style icon + label, used in the custom
// scrollable nav bar replacing the old <select> dropdown.
function TabIconButton({ tab, active, onClick, badge }) {
  const svgIcon = TabIcons[tab.id];
  return (
    <button onClick={onClick} style={{
      display: "flex", flexDirection: "column", alignItems: "center", gap: 4,
      background: "none", border: "none", cursor: "pointer", padding: "6px 10px",
      flexShrink: 0, fontFamily: "inherit", position: "relative",
    }}>
      <span style={{
        display: "flex", alignItems: "center", justifyContent: "center",
        width: 40, height: 40, borderRadius: "50%",
        background: active ? BRAND.white : "rgba(255,255,255,0.08)",
        border: `2px solid ${active ? BRAND.white : "rgba(255,255,255,0.35)"}`,
        color: active ? BRAND.navy : "rgba(255,255,255,0.75)",
        transition: "all 0.15s",
      }}>
        {svgIcon ? (
          <span style={{ width: 20, height: 20, display: "block" }}>{svgIcon}</span>
        ) : (
          <span style={{ fontSize: 18 }}>{tab.icon}</span>
        )}
      </span>
      {badge > 0 && (
        <span style={{ position: "absolute", top: 2, right: 4, background: "#DC2626", color: "#fff", fontSize: 9, fontWeight: 800, borderRadius: 99, minWidth: 15, height: 15, display: "flex", alignItems: "center", justifyContent: "center", padding: "0 3px", border: `1.5px solid ${BRAND.navy}` }}>
          {badge > 9 ? "9+" : badge}
        </span>
      )}
      <span style={{ fontSize: 9.5, fontWeight: active ? 700 : 500, color: active ? BRAND.white : "rgba(255,255,255,0.65)", whiteSpace: "nowrap" }}>
        {tab.label}
      </span>
    </button>
  );
}

// ─── Home Screen — grid of all tabs as circular card-style icons, shown as
// the landing page. Tapping any tile navigates straight to that tab.
function HomeScreen({ tabs, onSelect, user, allNotifs, backupReminder, jobs, standaloneTasks = [], onQuickAction, isDesktopView, onOpenChatbot }) {
  const [showQuickActions, setShowQuickActions] = useState(false);
  const dashboardStandaloneTasks = standaloneTasks;
  const dashboardShowsTeamTasks = canAdmin(user);

  const todayKey = new Date().toISOString().slice(0, 10);
  const firstName = user?.name?.split(" ")[0] || "there";
  const jobAssignedTasks = [];
  (jobs || []).forEach(j => {
    (j.jobTasks || []).forEach(t => {
      const assignees = parseAssignees(t.assignedTo);
      if (!dashboardShowsTeamTasks && !assignees.includes(user?.name)) return;
      if (t.status === "Completed") return;
      jobAssignedTasks.push({
        ...t,
        assignedTo: assignees,
        jobCustomer: j.customerName,
        jobId: j.id,
        isStandalone: false,
      });
    });
  });

  const standaloneAssignedTasks = (dashboardStandaloneTasks || [])
    .map(t => ({ ...t, assignedTo: parseAssignees(t.assignedTo), isStandalone: true }))
    .filter(t => (dashboardShowsTeamTasks || t.assignedTo.includes(user?.name)) && t.status !== "Completed");

  // Same active-task ordering philosophy as My Tasks: overdue first, then nearest follow-up/date assigned.
  const assignedTasks = [...jobAssignedTasks, ...standaloneAssignedTasks].sort((a, b) => {
    const now = new Date();
    const aOver = a.followUpDate && new Date(a.followUpDate) < now && a.status !== "Completed";
    const bOver = b.followUpDate && new Date(b.followUpDate) < now && b.status !== "Completed";
    if (aOver && !bOver) return -1;
    if (!aOver && bOver) return 1;
    return (a.followUpDate || a.dateAssigned || a.createdAt || "").localeCompare(
      b.followUpDate || b.dateAssigned || b.createdAt || ""
    );
  });

  const dueToday = assignedTasks.filter(t => (t.followUpDate || t.dueDate || "").slice(0,10) === todayKey);
  const inProgressJobs = (jobs || []).filter(j => j.status === "In Progress");
  const pendingAuthJobs = (jobs || []).filter(j => {
    const s = (j.workflowStage || "").toLowerCase();
    return s.includes("authorization") && !s.includes("signed");
  });
  const approvalCount =
    (allNotifs?.changeOrderApprovals?.length || 0) +
    (allNotifs?.purchaseApprovals?.length || 0);

  const recentJobs = [...(jobs || [])]
    .sort((a,b) => String(b.submittedAt || b.startDate || "").localeCompare(String(a.submittedAt || a.startDate || "")))
    .slice(0, isDesktopView ? 4 : 3);

  const now = new Date(); now.setHours(0,0,0,0);
  const weekEnd = new Date(now); weekEnd.setDate(weekEnd.getDate()+7);
  const scheduled = (jobs || [])
    .filter(j => j.scheduledDate)
    .map(j => ({ ...j, _d: new Date(j.scheduledDate + "T12:00:00") }))
    .filter(j => j._d >= now && j._d <= weekEnd)
    .sort((a,b) => a._d - b._d)
    .slice(0, 5);

  const taskPreview = assignedTasks.slice(0, isDesktopView ? 8 : 5);

  const metricCards = [
    { label: dashboardShowsTeamTasks ? "Team Tasks" : "My Tasks", value: assignedTasks.length, sub: dueToday.length ? `${dueToday.length} due today` : "Active tasks", icon:"tasks", tint:"#EFF6FF", ink:"#1D4ED8", tab:"tasks" },
    { label:"Jobs", value: inProgressJobs.length, sub:"In progress", icon:"jobs", tint:"#F0FDF4", ink:"#15803D", tab:"jobs" },
    { label:"Pending", value: pendingAuthJobs.length + approvalCount, sub:"Authorizations / approvals", icon:"workauths", tint:"#FFF7E6", ink:"#B45309", tab:"workauths" },
    { label:"Scheduled", value: scheduled.length, sub:"Next 7 days", icon:"calendar", tint:"#F5F3FF", ink:"#6D28D9", tab:"calendar" },
  ];

  const statusStyle = (status) => STATUS_META[status] || { bg:"#F1F5F9", text:"#475569", border:"#CBD5E1" };

  return (
    <div className="sh-dashboard">
      {showQuickActions && (
        <QuickActionsPanel
          user={user} jobs={jobs || []}
          onClose={() => setShowQuickActions(false)}
          onNavigate={(action) => { setShowQuickActions(false); onQuickAction(action); }}
        />
      )}

      <div className="sh-dash-hero">
        <div>
          <div className="sh-dash-title">Welcome back, {firstName}!</div>
          <div className="sh-dash-subtitle">Here's what's happening with your projects today.</div>
        </div>
        <div className="sh-dash-actions">
          {canSubmitJobs(user) && (
            <button className="sh-action-primary" onClick={() => onSelect("submit")}>＋ <span>New Job</span></button>
          )}
          <button className="sh-action-secondary" onClick={() => setShowQuickActions(true)}>⚡ <span>Quick Actions</span></button>
        </div>
      </div>

      <GpsClockInNudge user={user} jobs={jobs || []} />

      <div className="sh-metric-grid">
        {metricCards.map(card => {
          const svgIcon = TabIcons[card.icon];
          return (
            <button key={card.label} className="sh-metric-card" onClick={() => onSelect(card.tab)}>
              <span className="sh-metric-icon" style={{ background:card.tint, color:card.ink }}>
                {svgIcon ? <span>{svgIcon}</span> : "•"}
              </span>
              <span className="sh-metric-number">{card.value}</span>
              <span className="sh-metric-copy"><strong>{card.label}</strong><small>{card.sub}</small></span>
            </button>
          );
        })}
      </div>

      <div className="sh-dash-columns">
        <section className="sh-panel">
          <div className="sh-panel-head">
            <strong>{dashboardShowsTeamTasks ? "Team Tasks" : "My Tasks"}</strong>
            <button onClick={() => onSelect("tasks")}>View All</button>
          </div>
          <div className="sh-panel-body">
            {taskPreview.length === 0 ? (
              <div className="sh-empty">{dashboardShowsTeamTasks ? "No active team tasks." : "No active tasks assigned to you."}</div>
            ) : taskPreview.map((t,i) => {
              const p = PRIORITIES.find(x => x.value === t.priority) || PRIORITIES[2];
              return (
                <button key={t.id || i} className="sh-list-row" onClick={() => onSelect("tasks")}>
                  <span className="sh-dot" style={{ background:p.color }} />
                  <span className="sh-row-main">
                    <strong>{t.title}</strong>
                    <small>{t.isStandalone ? "Action item" : (t.jobCustomer || "General task")}{t.followUpDate ? ` · ${fmtDate(t.followUpDate)}` : ""}</small>
                  </span>
                  <span className="sh-priority" style={{ color:p.color, background:p.color+"12" }}>{p.label}</span>
                </button>
              );
            })}
          </div>
        </section>

        <section className="sh-panel">
          <div className="sh-panel-head">
            <strong>Recent Jobs</strong>
            <button onClick={() => onSelect("jobs")}>View All</button>
          </div>
          <div className="sh-panel-body">
            {recentJobs.length === 0 ? (
              <div className="sh-empty">No jobs yet.</div>
            ) : recentJobs.map(j => {
              const st = statusStyle(j.status);
              return (
                <button key={j.id} className="sh-job-row" onClick={() => onSelect("jobs")}>
                  <span className="sh-row-main">
                    <strong>{j.customerName || j.id}</strong>
                    <small>{j.address || j.jobType || "S&H project"}</small>
                  </span>
                  <span className="sh-status-pill" style={{ color:st.text, background:st.bg, borderColor:st.border }}>{j.status || "New"}</span>
                </button>
              );
            })}
          </div>
        </section>

        <section className="sh-panel">
          <div className="sh-panel-head">
            <strong>This Week's Schedule</strong>
            <button onClick={() => onSelect("calendar")}>View Calendar</button>
          </div>
          <div className="sh-panel-body">
            {scheduled.length === 0 ? (
              <div className="sh-empty">Nothing scheduled in the next 7 days.</div>
            ) : scheduled.map(j => (
              <button key={j.id} className="sh-schedule-row" onClick={() => onSelect("calendar")}>
                <span className="sh-schedule-date">
                  <strong>{j._d.toLocaleDateString(undefined,{weekday:"short"})}</strong>
                  <small>{j._d.toLocaleDateString(undefined,{month:"short",day:"numeric"})}</small>
                </span>
                <span className="sh-row-main">
                  <strong>{j.customerName}</strong>
                  <small>{j.address || j.jobType || ""}</small>
                </span>
              </button>
            ))}
          </div>
        </section>
      </div>

    </div>
  );
}

function SHDesktopSidebar({ tabs, activeTab, onSelect, backupReminder, onAskErik }) {
  const navRef = useRef(null);
  const scrollTarget = useRef(0);
  const scrollRaf = useRef(null);

  useEffect(() => {
    const el = navRef.current;
    if (!el) return;
    scrollTarget.current = el.scrollTop;

    const onWheel = (e) => {
      if (!e.deltaY) return;
      e.preventDefault();
      const max = Math.max(0, el.scrollHeight - el.clientHeight);
      scrollTarget.current = Math.max(0, Math.min(max, scrollTarget.current + e.deltaY * 0.68));

      if (scrollRaf.current) cancelAnimationFrame(scrollRaf.current);
      const ease = () => {
        const delta = scrollTarget.current - el.scrollTop;
        el.scrollTop += delta * 0.145;
        if (Math.abs(delta) > 0.55) {
          scrollRaf.current = requestAnimationFrame(ease);
        } else {
          el.scrollTop = scrollTarget.current;
          scrollRaf.current = null;
        }
      };
      scrollRaf.current = requestAnimationFrame(ease);
    };

    el.addEventListener("wheel", onWheel, { passive: false });
    return () => {
      el.removeEventListener("wheel", onWheel);
      if (scrollRaf.current) cancelAnimationFrame(scrollRaf.current);
    };
  }, []);

  return (
    <aside
      className="sh-sidebar"
      style={{
        position:"fixed", left:0, top:86, bottom:0, width:238, minHeight:0, height:"auto",
        zIndex:185, overflow:"hidden", background:"#FFFFFF", borderRight:"1px solid #D7E2F0",
        boxShadow:"4px 0 20px rgba(3,30,74,.14)"
      }}
    >
      <div
        aria-hidden="true"
        style={{
          position:"absolute", right:7, top:92, zIndex:205, width:29, height:118,
          borderRadius:16, background:"rgba(13,59,128,.08)", border:"1px solid rgba(13,59,128,.13)",
          boxShadow:"0 4px 12px rgba(13,59,128,.08)", display:"flex", flexDirection:"column",
          alignItems:"center", justifyContent:"space-between", padding:"6px 0", color:"#0D3B80",
          pointerEvents:"none", backdropFilter:"blur(6px)"
        }}
      >
        <span style={{fontSize:17,fontWeight:950,lineHeight:1}}>⌃</span>
        <span style={{
          fontSize:8,fontWeight:900,letterSpacing:1.6,writingMode:"vertical-rl",
          transform:"rotate(180deg)",opacity:.7
        }}>SCROLL</span>
        <span style={{fontSize:17,fontWeight:950,lineHeight:1}}>⌄</span>
      </div>

      <nav
        ref={navRef}
        className="sh-sidebar-nav"
        style={{
          position:"absolute", inset:"0", overflowY:"auto", overflowX:"hidden",
          padding:"96px 18px 210px 16px", display:"flex", flexDirection:"column", gap:5,
          scrollbarWidth:"none", msOverflowStyle:"none", overscrollBehavior:"contain",
          WebkitOverflowScrolling:"touch",
          WebkitMaskImage:"linear-gradient(to bottom,transparent 0,#000 24px,#000 calc(100% - 28px),transparent 100%)",
          maskImage:"linear-gradient(to bottom,transparent 0,#000 24px,#000 calc(100% - 28px),transparent 100%)"
        }}
      >
        {tabs.map(t => {
          const active = activeTab === t.id;
          const svgIcon = TabIcons[t.id];
          const badge = t.id === "backup" && backupReminder ? 1 : 0;
          return (
            <button key={t.id} className={active ? "sh-side-item active" : "sh-side-item"} onClick={() => onSelect(t.id)}>
              <span className="sh-side-icon">{svgIcon ? svgIcon : <span>{t.icon}</span>}</span>
              <span>{t.label}</span>
              {badge > 0 && <i>{badge}</i>}
            </button>
          );
        })}
      </nav>

      <div className="sh-sidebar-bottom" style={{zIndex:210}}>
        <div className="sh-sidebar-restoration" aria-hidden="true">
          <span className="sh-restoration-small">Restoration</span>
          <span className="sh-restoration-large">Done Right!</span>
          <span className="sh-restoration-swoosh" />
        </div>
      </div>
    </aside>
  );
}

function SHMobileBottomNav({ tabs = [], activeTab, onSelect, taskBadge = 0 }) {
  // Mobile navigation intentionally exposes every permitted page in one
  // horizontally swipeable rail — no separate “More” menu.
  return (
    <nav className="sh-bottom-nav" aria-label="App pages">
      {tabs.map(t => {
        const icon = TabIcons[t.id] || <span style={{fontSize:18}}>{t.icon}</span>;
        return (
          <button
            key={t.id}
            className={activeTab === t.id ? "active" : ""}
            onClick={() => onSelect(t.id)}
            aria-current={activeTab === t.id ? "page" : undefined}
          >
            <span className="sh-mobile-nav-circle">{icon}</span>
            <small>{t.label}</small>
            {t.id === "tasks" && taskBadge > 0 && <i>{taskBadge > 9 ? "9+" : taskBadge}</i>}
          </button>
        );
      })}
    </nav>
  );
}

function SHMoreMenu({ tabs, activeTab, onSelect, onClose, user }) {
  const hiddenFromBottom = new Set(["home","tasks","jobs","calendar"]);
  const moreTabs = tabs.filter(t => !hiddenFromBottom.has(t.id));
  return (
    <div className="sh-more-backdrop" onClick={onClose}>
      <div className="sh-more-sheet" onClick={e => e.stopPropagation()}>
        <div className="sh-more-handle" />
        <div className="sh-more-title"><strong>More</strong><button onClick={onClose}>×</button></div>
        <div className="sh-more-grid">
          {moreTabs.map(t => (
            <button key={t.id} className={activeTab === t.id ? "active" : ""} onClick={() => { onSelect(t.id); onClose(); }}>
              <span>{TabIcons[t.id] || t.icon}</span>
              <small>{t.label}</small>
            </button>
          ))}
        </div>
      </div>

      <section className="sh-panel sh-quick-actions-panel">
        <div className="sh-panel-head">
          <strong>Quick Actions</strong>
        </div>
        <div className="sh-quick-actions-grid">
          {canSubmitJobs(user) && (
            <button onClick={() => onSelect("submit")}>
              <span>{TabIcons.jobs}</span>
              <small>New Job</small>
            </button>
          )}
          <button onClick={() => onSelect("tasks")}>
            <span>{TabIcons.tasks}</span>
            <small>New Task</small>
          </button>
          <button onClick={() => onSelect("receipts")}>
            <span>{TabIcons.receipts}</span>
            <small>Add Receipt</small>
          </button>
          <button onClick={() => onSelect("mileage")}>
            <span>{TabIcons.mileage}</span>
            <small>Log Mileage</small>
          </button>
        </div>
      </section>
    </div>
  );
}

// ─── GPS Clock-In Nudge ─────────────────────────────────────────────────────
// Runs once when the Home screen is opened: if the crew member is standing
// near one of their own assigned jobs and isn't already clocked in anywhere,
// shows a one-tap "clock in?" banner instead of relying on them to remember.
//
// HONEST LIMITATION: like mileage tracking, this only works while the app is
// open — a browser PWA can't watch location in the background or wake itself
// up when someone arrives. It's a nudge when they open the app on-site, not
// a silent geofence trigger. Job addresses are geocoded once (via the free
// Nominatim service, same as Contacts) and cached on the job so repeat
// visits don't re-geocode.
const GPS_CLOCKIN_RADIUS_MILES = 0.3;
function GpsClockInNudge({ user, jobs }) {
  const [nearbyJob, setNearbyJob] = useState(null);
  const [busy, setBusy] = useState(false);
  const [toast, setToast] = useState(null);
  const checkedRef = useRef(false);

  useEffect(() => {
    if (checkedRef.current) return; // once per mount, not on every re-render
    checkedRef.current = true;
    (async () => {
      try {
        // Already clocked in somewhere? Nothing to nudge about.
        const openRows = await sbFetch(`time_entries?user_name=eq.${encodeURIComponent(user.name)}&clock_out=is.null&limit=1`).catch(() => []);
        if (openRows?.length) return;

        const here = await getUserLocation();
        if (!here) return; // denied or unavailable — fail silent, no interruption

        const today = new Date().toISOString().slice(0, 10);
        const candidates = (jobs || []).filter(j =>
          parseCrew(j.crew).includes(user.name) &&
          !["Done", "Cancelled"].includes(j.status) &&
          j.address &&
          (() => { try { return localStorage.getItem(`sh_gps_dismiss_${j.id}_${today}`) !== "1"; } catch { return true; } })()
        ).slice(0, 6); // bound how many we'll ever geocode in one pass

        let best = null, bestDist = Infinity;
        for (const j of candidates) {
          let lat = j.lat, lng = j.lng;
          if (lat == null || lng == null) {
            const coords = await geocodeAddress(j.address);
            if (!coords) continue;
            lat = coords.lat; lng = coords.lng;
            updateJobField(j.id, "lat", lat).catch(() => {});
            updateJobField(j.id, "lng", lng).catch(() => {});
          }
          const dist = milesBetween(here.lat, here.lng, lat, lng);
          if (dist < bestDist) { bestDist = dist; best = j; }
        }
        if (best && bestDist <= GPS_CLOCKIN_RADIUS_MILES) setNearbyJob(best);
      } catch {}
    })();
  }, [user.name, jobs]);

  if (!nearbyJob) return null;

  async function clockIn() {
    setBusy(true);
    try {
      const entry = { id: "TE-" + Date.now(), job_id: nearbyJob.id, job_customer: nearbyJob.customerName || null, user_name: user.name, clock_in: new Date().toISOString(), clock_out: null, duration_minutes: null, notes: "" };
      await sbFetch("time_entries", { method: "POST", body: JSON.stringify(entry) });
      setToast({ msg: `Clocked in on ${nearbyJob.customerName}`, ok: true });
      setNearbyJob(null);
    } catch {
      setToast({ msg: "Couldn't clock in — try again from Quick Actions", ok: false });
    }
    setBusy(false);
    setTimeout(() => setToast(null), 3000);
  }

  function dismiss() {
    try { localStorage.setItem(`sh_gps_dismiss_${nearbyJob.id}_${new Date().toISOString().slice(0,10)}`, "1"); } catch {}
    setNearbyJob(null);
  }

  return (
    <>
      {toast && <Toast msg={toast.msg} ok={toast.ok} />}
      <div style={{ background: "#EFF6FF", border: "1.5px solid #93C5FD", borderRadius: 12, padding: "12px 14px", marginBottom: 14, display: "flex", alignItems: "center", gap: 10 }}>
        <span style={{ fontSize: 22, flexShrink: 0 }}>📍</span>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: 12.5, fontWeight: 700, color: "#1D4ED8" }}>Looks like you're at {nearbyJob.customerName}'s job</div>
          <div style={{ fontSize: 11, color: "#3B82F6", marginTop: 1 }}>{nearbyJob.address}</div>
        </div>
        <button onClick={dismiss} style={{ background: "none", border: "none", color: "#93C5FD", fontSize: 16, cursor: "pointer", padding: 4, flexShrink: 0 }}>✕</button>
        <button onClick={clockIn} disabled={busy} style={{ background: "#1D4ED8", border: "none", borderRadius: 8, color: "#fff", fontSize: 12, fontWeight: 700, padding: "8px 12px", cursor: "pointer", flexShrink: 0, opacity: busy ? 0.6 : 1 }}>
          {busy ? "…" : "Clock In"}
        </button>
      </div>
    </>
  );
}

// One-tap access from the Home screen to the three things field crew do
// constantly: clock in/out, start a mileage trip, and log a receipt.
// Clock in/out is fully self-contained here (it's just a simple time_entries
// row, safe to handle inline). Mileage and Receipts are more involved
// (mileage in particular runs a live GPS watch that only exists as long as
// the Mileage tab itself is mounted), so those two instead jump straight to
// their real tab and auto-trigger the action on arrival, via onNavigate.
function QuickActionsPanel({ user, jobs, onClose, onNavigate }) {
  const [loading, setLoading] = useState(true);
  const [activeEntry, setActiveEntry] = useState(null);
  const [elapsed, setElapsed] = useState(0);
  const [clockJobId, setClockJobId] = useState("");
  const [busy, setBusy] = useState(false);
  const [toast, setToast] = useState(null);
  const timerRef = useRef(null);

  useEffect(() => {
    (async () => {
      try {
        const rows = await sbFetch(`time_entries?user_name=eq.${encodeURIComponent(user.name)}&order=clock_in.desc&limit=5`);
        const open = (rows || []).find(r => !r.clock_out);
        if (open) {
          setActiveEntry(open);
          setClockJobId(open.job_id || "");
          setElapsed(Math.floor((Date.now() - new Date(open.clock_in).getTime()) / 1000));
        }
      } catch {}
      setLoading(false);
    })();
  }, [user.name]);

  useEffect(() => {
    if (activeEntry) timerRef.current = setInterval(() => setElapsed(s => s + 1), 1000);
    else clearInterval(timerRef.current);
    return () => clearInterval(timerRef.current);
  }, [activeEntry]);

  function fmtElapsed(secs) {
    const h = Math.floor(secs / 3600), m = Math.floor((secs % 3600) / 60), s = secs % 60;
    return h > 0 ? `${h}h ${String(m).padStart(2, "0")}m` : `${m}:${String(s).padStart(2, "0")}`;
  }

  async function toggleClock() {
    setBusy(true);
    try {
      if (activeEntry) {
        const now = new Date().toISOString();
        const mins = Math.round(elapsed / 60);
        await sbFetch(`time_entries?id=eq.${activeEntry.id}`, { method: "PATCH", body: JSON.stringify({ clock_out: now, duration_minutes: mins }) });
        setActiveEntry(null); setElapsed(0);
        setToast({ msg: `Clocked out — ${mins}m logged`, ok: true });
      } else {
        const job = jobs.find(j => j.id === clockJobId);
        const entry = { id: "TE-" + Date.now(), job_id: clockJobId || null, job_customer: job?.customerName || null, user_name: user.name, clock_in: new Date().toISOString(), clock_out: null, duration_minutes: null, notes: "" };
        await sbFetch("time_entries", { method: "POST", body: JSON.stringify(entry) });
        setActiveEntry(entry); setElapsed(0);
        setToast({ msg: `Clocked in${job ? " on " + job.customerName : ""}`, ok: true });
      }
    } catch {
      setToast({ msg: "Something went wrong", ok: false });
    }
    setTimeout(() => setToast(null), 3000);
    setBusy(false);
  }

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.5)", zIndex: 60, display: "flex", alignItems: "flex-end" }} onClick={onClose}>
      <div onClick={e => e.stopPropagation()} style={{ background: BRAND.offWhite, borderTopLeftRadius: 20, borderTopRightRadius: 20, width: "100%", maxWidth: 520, margin: "0 auto", padding: 20, paddingBottom: 28, maxHeight: "85vh", overflowY: "auto" }}>
        {toast && <Toast msg={toast.msg} ok={toast.ok} />}
        <div style={{ width: 40, height: 4, background: BRAND.border, borderRadius: 99, margin: "0 auto 16px" }} />
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
          <div style={{ fontSize: 17, fontWeight: 800, color: BRAND.navy }}>⚡ Quick Actions</div>
          <button onClick={onClose} style={{ background: "none", border: "none", fontSize: 22, color: BRAND.muted, cursor: "pointer", lineHeight: 1 }}>×</button>
        </div>

        {/* Clock In/Out — fully inline, no navigation needed */}
        <div style={{ ...S.card, background: activeEntry ? "#F0FDF4" : BRAND.white, border: `1.5px solid ${activeEntry ? "#BBF7D0" : BRAND.border}` }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <div>
              <div style={{ fontSize: 13, fontWeight: 700, color: BRAND.navy }}>⏱ {activeEntry ? "Clocked In" : "Clock In / Out"}</div>
              {activeEntry ? (
                <div style={{ fontSize: 12, color: "#15803D", marginTop: 2 }}>{fmtElapsed(elapsed)} elapsed{activeEntry.job_customer ? ` · ${activeEntry.job_customer}` : ""}</div>
              ) : (
                <div style={{ fontSize: 12, color: BRAND.muted, marginTop: 2 }}>{loading ? "Checking status…" : "Not clocked in"}</div>
              )}
            </div>
            <button onClick={toggleClock} disabled={busy || loading} style={{ background: activeEntry ? "#DC2626" : "#16A34A", border: "none", borderRadius: 8, color: "#fff", fontWeight: 700, fontSize: 12, padding: "8px 14px", cursor: "pointer", opacity: (busy || loading) ? 0.6 : 1, flexShrink: 0 }}>
              {activeEntry ? "Clock Out" : "Clock In"}
            </button>
          </div>
          {!activeEntry && !loading && (
            <select value={clockJobId} onChange={e => setClockJobId(e.target.value)} style={{ ...S.input, marginTop: 10, appearance: "none" }}>
              <option value="">— No specific job —</option>
              {jobs.map(j => <option key={j.id} value={j.id}>{j.id} · {j.customerName}</option>)}
            </select>
          )}
        </div>

        {/* Mileage — jumps to the real tab and auto-starts tracking there */}
        <button onClick={() => onNavigate("startTrip")} style={{ ...S.card, display: "flex", justifyContent: "space-between", alignItems: "center", width: "100%", textAlign: "left", cursor: "pointer", border: `1.5px solid ${BRAND.border}`, background: BRAND.white }}>
          <div>
            <div style={{ fontSize: 13, fontWeight: 700, color: BRAND.navy }}>🚗 Start Mileage Trip</div>
            <div style={{ fontSize: 12, color: BRAND.muted, marginTop: 2 }}>Opens live GPS tracking</div>
          </div>
          <span style={{ fontSize: 20, color: BRAND.muted }}>›</span>
        </button>

        {/* Receipt — jumps to the real tab with the Add form already open */}
        <button onClick={() => onNavigate("addReceipt")} style={{ ...S.card, display: "flex", justifyContent: "space-between", alignItems: "center", width: "100%", textAlign: "left", cursor: "pointer", border: `1.5px solid ${BRAND.border}`, background: BRAND.white, marginBottom: 0 }}>
          <div>
            <div style={{ fontSize: 13, fontWeight: 700, color: BRAND.navy }}>🧾 Add Receipt</div>
            <div style={{ fontSize: 12, color: BRAND.muted, marginTop: 2 }}>Snap a photo or enter manually</div>
          </div>
          <span style={{ fontSize: 20, color: BRAND.muted }}>›</span>
        </button>
      </div>
    </div>
  );
}

function Toast({ msg, ok = true }) {
  return (
    <div style={{ position: "fixed", bottom: 90, left: "50%", transform: "translateX(-50%)", background: ok ? BRAND.navy : "#DC2626", color: BRAND.white, borderRadius: 10, padding: "10px 20px", fontSize: 13, fontWeight: 700, zIndex: 100, whiteSpace: "nowrap", boxShadow: "0 4px 16px rgba(0,0,0,0.2)", border: `1px solid ${ok ? BRAND.gold : "#FF6B6B"}` }}>
      {ok ? "✓ " : "✗ "}{msg}
    </div>
  );
}

// ─── Login ────────────────────────────────────────────────────────────────────
// ─── Authentication — username/password with hashed credentials ──────────────
// Default starter password — every employee begins with this same password.
// They are forced to set their own unique password (and provide contact info)
// the very first time they log in.
const DEFAULT_STARTER_PASSWORD = "LittleBrotherisAlwaysBetter";

// Passwords are never stored in plaintext. We hash with SHA-256 + a random
// per-user salt using the browser's built-in SubtleCrypto API (no extra
// dependency needed). This is a lightweight scheme appropriate for an
// internal company tool — not meant to replace a full auth provider.
async function hashPassword(password, salt) {
  const enc = new TextEncoder();
  const data = enc.encode(salt + ":" + password);
  const hashBuffer = await crypto.subtle.digest("SHA-256", data);
  return Array.from(new Uint8Array(hashBuffer)).map(b => b.toString(16).padStart(2, "0")).join("");
}
function generateSalt() {
  const arr = new Uint8Array(16);
  crypto.getRandomValues(arr);
  return Array.from(arr).map(b => b.toString(16).padStart(2, "0")).join("");
}
function generateTempPassword() {
  const chars = "ABCDEFGHJKMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789";
  let out = "";
  for (let i = 0; i < 10; i++) out += chars[Math.floor(Math.random() * chars.length)];
  return out;
}

async function fetchCredentials() {
  const rows = await sbFetch("user_credentials?select=user_id,salt,password_hash,must_reset,updated_at");
  return rows || [];
}
async function fetchCredentialFor(userId) {
  const rows = await sbFetch(`user_credentials?user_id=eq.${userId}&select=user_id,salt,password_hash,must_reset`);
  return rows?.[0] || null;
}
async function setUserPassword(userId, newPassword, mustReset = false) {
  const salt = generateSalt();
  const hash = await hashPassword(newPassword, salt);
  const existing = await sbFetch(`user_credentials?user_id=eq.${userId}&select=user_id`);
  const row = { user_id: userId, salt, password_hash: hash, must_reset: mustReset, updated_at: new Date().toISOString() };
  if (existing?.length) {
    await sbFetch(`user_credentials?user_id=eq.${userId}`, { method: "PATCH", body: JSON.stringify(row) });
  } else {
    await sbFetch("user_credentials", { method: "POST", body: JSON.stringify(row) });
  }
}
async function verifyPassword(userId, password) {
  const cred = await fetchCredentialFor(userId);
  if (!cred) {
    // No credential row yet — everyone starts on the same default password.
    // If it matches, treat this as a forced first-time setup (password + contact info).
    if (password === DEFAULT_STARTER_PASSWORD) {
      return { ok: true, mustReset: true, isFirstLogin: true };
    }
    return { ok: false, reason: "no-credential" };
  }
  const hash = await hashPassword(password, cred.salt);
  if (hash !== cred.password_hash) return { ok: false, reason: "wrong-password" };
  return { ok: true, mustReset: !!cred.must_reset, isFirstLogin: false };
}

// ── Passwordless email one-time code ─────────────────────────────────────────
// Uses Supabase Auth's email OTP endpoint for delivery/verification, while the
// app continues to use its existing employee roster and custom password system.
// The Supabase auth session is only used to prove possession of the saved email;
// successful verification then signs the matching S&H employee into this app.
async function requestEmailLoginCode(email) {
  const res = await fetch(`${SUPABASE_URL}/auth/v1/otp`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "apikey": SUPABASE_KEY,
      "Authorization": `Bearer ${SUPABASE_KEY}`,
    },
    body: JSON.stringify({ email, create_user: true }),
  });
  if (!res.ok) {
    let msg = "Could not send the code.";
    try {
      const data = await res.json();
      msg = data?.msg || data?.message || data?.error_description || msg;
    } catch {}
    throw new Error(msg);
  }
  return true;
}

async function verifyEmailLoginCode(email, token) {
  const res = await fetch(`${SUPABASE_URL}/auth/v1/verify`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "apikey": SUPABASE_KEY,
      "Authorization": `Bearer ${SUPABASE_KEY}`,
    },
    body: JSON.stringify({ type: "email", email, token }),
  });
  if (!res.ok) {
    let msg = "That code is invalid or expired.";
    try {
      const data = await res.json();
      msg = data?.msg || data?.message || data?.error_description || msg;
    } catch {}
    throw new Error(msg);
  }
  return await res.json().catch(() => ({}));
}

function maskEmailAddress(email) {
  const value = String(email || "");
  const [name, domain] = value.split("@");
  if (!name || !domain) return value;
  const shown = name.length <= 2 ? name[0] || "" : name.slice(0, 2);
  return `${shown}${"*".repeat(Math.max(2, name.length - shown.length))}@${domain}`;
}

