// ─── ModalShell ───────────────────────────────────────────────────────────────
// Reusable wrapper for all popups. Provides backdrop, centering, and an
// expand-to-fullscreen toggle button in the top-right corner.
function ModalShell({ onClose, children, maxWidth = 520, zIndex = 500 }) {
  const [expanded, setExpanded] = useState(false);
  return (
    <div
      onClick={onClose}
      style={{
        position: "fixed", inset: 0, zIndex,
        background: "rgba(0,0,0,0.65)",
        display: "flex", alignItems: "center", justifyContent: "center",
        padding: expanded ? 0 : "16px 12px",
        transition: "padding 0.2s",
      }}
    >
      <div
        onClick={e => e.stopPropagation()}
        style={{
          background: "#fff",
          borderRadius: expanded ? 0 : 18,
          width: "100%",
          maxWidth: expanded ? "100%" : maxWidth,
          height: expanded ? "100%" : undefined,
          maxHeight: expanded ? "100%" : "90vh",
          display: "flex",
          flexDirection: "column",
          boxShadow: expanded ? "none" : "0 8px 40px rgba(0,0,0,0.3)",
          transition: "border-radius 0.2s, max-width 0.2s",
          position: "relative",
          overflow: "hidden",
        }}
      >
        {/* Expand / collapse button */}
        <button
          onClick={() => setExpanded(e => !e)}
          title={expanded ? "Collapse" : "Expand to full screen"}
          style={{
            position: "absolute", top: 10, right: expanded ? 44 : 44,
            width: 28, height: 28, borderRadius: 7,
            background: "rgba(0,0,0,0.07)", border: "none",
            display: "flex", alignItems: "center", justifyContent: "center",
            cursor: "pointer", zIndex: 10, fontSize: 14, color: BRAND.muted,
            flexShrink: 0,
          }}
        >
          {expanded ? "⊡" : "⤢"}
        </button>
        {children}
      </div>
    </div>
  );
}


// ─── Hold Up Modal ────────────────────────────────────────────────────────────
function HoldUpModal({ errors, onClose, onFix }) {
  return (
    <div style={{ position:"fixed", inset:0, background:"rgba(0,0,0,0.65)", zIndex:600,
      display:"flex", alignItems:"center", justifyContent:"center", padding:"20px 16px" }}>
      <div style={{ width:"100%", maxWidth:320, position:"relative", paddingTop:90 }}>
        {/* Sticker — half above card */}
        <img src={HOLDUP_IMG} alt="Hold Up!"
          style={{ position:"absolute", top:0, left:"50%", transform:"translateX(-50%)",
            width:180, zIndex:10, filter:"drop-shadow(0 4px 14px rgba(0,0,0,0.3))" }} />
        <div style={{ background:"#fff", borderRadius:20, overflow:"hidden",
          boxShadow:"0 8px 48px rgba(0,0,0,0.4)" }}>
          {/* Navy header */}
          <div style={{ background:"#1B3A6B", height:54, display:"flex",
            alignItems:"flex-end", justifyContent:"flex-end", padding:"0 12px 10px" }}>
            <button onClick={onClose} style={{ background:"none", border:"none",
              color:"rgba(255,255,255,0.7)", fontSize:20, cursor:"pointer", lineHeight:1 }}>×</button>
          </div>
          <div style={{ padding:"14px 18px 20px" }}>
            <div style={{ fontSize:18, fontWeight:800, color:"#1B3A6B",
              textAlign:"center", marginBottom:4 }}>Hold up!</div>
            <div style={{ fontSize:12, color:"#5A7099", textAlign:"center",
              marginBottom:14, lineHeight:1.45 }}>
              A few required fields are missing before you can continue.
            </div>
            <div style={{ display:"flex", flexDirection:"column", gap:7, marginBottom:16 }}>
              {errors.map((err, i) => (
                <div key={i} style={{ display:"flex", alignItems:"center", gap:10,
                  background:"#FEF2F2", border:"1px solid #FECACA", borderRadius:10, padding:"9px 13px" }}>
                  <span style={{ fontSize:14, flexShrink:0 }}>⚠️</span>
                  <span style={{ fontSize:13, fontWeight:700, color:"#991B1B" }}>{err}</span>
                </div>
              ))}
            </div>
            <div style={{ display:"flex", gap:8 }}>
              <button onClick={onClose}
                style={{ flex:1, padding:11, border:"1.5px solid #D1D9E8", borderRadius:11,
                  background:"#fff", fontSize:13, fontWeight:700, color:"#5A7099", cursor:"pointer" }}>
                Dismiss
              </button>
              {onFix && (
                <button onClick={() => { onFix(); onClose(); }}
                  style={{ flex:2, padding:11, border:"none", borderRadius:11,
                    background:"#1B3A6B", color:"#fff", fontSize:13, fontWeight:800, cursor:"pointer" }}>
                  → Fix These
                </button>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

