function PaintVisualizerTool({ onClose }) {
  const [step, setStep] = useState("photo"); // photo | brand | color | surface | render | result
  const [photo, setPhoto] = useState(null); // data URL
  const [brand, setBrand] = useState(null);
  const [collection, setCollection] = useState(null);
  const [selectedColor, setSelectedColor] = useState(null);
  const [surface, setSurface] = useState("exterior walls"); // what to paint
  const [rendering, setRendering] = useState(false);
  const [renderUrl, setRenderUrl] = useState(null);
  const [analysis, setAnalysis] = useState(null);
  const [error, setError] = useState("");
  const [paintMaskMode, setPaintMaskMode] = useState(false);
  const [paintMaskSize, setPaintMaskSize] = useState(40);
  const paintMaskRef = useRef();
  const paintMaskDrawing = useRef(false);
  const cameraRef = useRef();
  const fileRef = useRef();

  function initPaintMask() {
    const canvas = paintMaskRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    ctx.fillStyle = "black";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }
  function paintOnMask(e) {
    if (!paintMaskDrawing.current) return;
    const canvas = paintMaskRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    const rect = canvas.getBoundingClientRect();
    const src = e.touches ? e.touches[0] : e;
    const x = (src.clientX - rect.left) * (canvas.width / rect.width);
    const y = (src.clientY - rect.top) * (canvas.height / rect.height);
    ctx.fillStyle = "white";
    ctx.beginPath();
    ctx.arc(x, y, paintMaskSize, 0, Math.PI * 2);
    ctx.fill();
  }

  async function startPreciseRender() {
    if (!photo || !selectedColor) return;
    const canvas = paintMaskRef.current;
    const maskB64 = canvas ? canvas.toDataURL("image/png") : null;
    setRendering(true);
    setError("");
    setPaintMaskMode(false);
    setStep("render");
    try {
      const prompt = `Paint the ${surface} in ${brand} ${selectedColor.name}, ${getColorDescription(selectedColor.hex)} color (${selectedColor.hex}), professional paint finish, photorealistic`;
      const repResp = await fetch("/api/replicate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ prompt, image: photo, mask: maskB64, num_inference_steps: 25, guidance_scale: 8 })
      });
      const repData = await repResp.json();
      if (!repResp.ok) throw new Error(repData.error || "Replicate error");
      const out = Array.isArray(repData.output) ? repData.output[0] : repData.output;
      if (!out) throw new Error("No output");
      setRenderUrl(out);
      setAnalysis(`${brand} ${selectedColor.name} (${selectedColor.num}) on ${surface} — precise inpaint`);
      setStep("result");
    } catch(e) {
      setError(e.message || "Precise render failed — try standard render");
      setStep("color");
    }
    setRendering(false);
  }

  async function startRender() {
    if (!photo || !selectedColor) return;
    setRendering(true);
    setError("");
    setStep("render");
    try {
      const b64 = photo.split(",")[1];

      // Step 1: Claude Vision — describe ONLY the color change, not a new scene
      const resp = await fetch("/api/claude", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-6",
          max_tokens: 300,
          messages: [{
            role: "user",
            content: [
              { type: "image", source: { type: "base64", media_type: "image/jpeg", data: b64 } },
              { type: "text", text: `You are a professional paint color visualization expert.

This photo will be used as the BASE IMAGE for inpainting — the house/room will be preserved exactly.
Describe ONLY the color change being made to the ${surface}.
Do NOT describe the overall scene, the house structure, surroundings, or anything else in the photo.

Write a short inpainting prompt (under 80 words) starting with exactly:
"Paint the ${surface} in ${brand} ${selectedColor.name} (${selectedColor.num}), "

Then describe: the exact paint color (${getColorDescription(selectedColor.hex)} tone, hex ${selectedColor.hex}), finish (matte/eggshell/satin), how it looks on this surface. Keep everything else in the photo identical.

Return ONLY the prompt, nothing else.` }
            ]
          }]
        })
      });
      const data = await resp.json();
      if (!resp.ok) throw new Error(data?.error?.message || "API error " + resp.status);
      const prompt = (data.content||[]).filter(b=>b.type==="text").map(b=>b.text).join("").trim();

      setAnalysis(`${brand} ${selectedColor.name} (${selectedColor.num}) on ${surface}`);

      // Step 2: Try Replicate inpainting first (preserves photo exactly)
      let outputUrl = null;
      try {
        const repResp = await fetch("/api/replicate", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            prompt,
            image: photo,
            mask: null, // no mask = Replicate auto-detects the surface
            num_inference_steps: 25,
            guidance_scale: 8,
            strength: 0.75,
          })
        });
        const repData = await repResp.json();
        if (repResp.ok && repData.output) {
          outputUrl = Array.isArray(repData.output) ? repData.output[0] : repData.output;
        }
      } catch(_) {}

      // Step 3: Fallback to Pollinations img2img if Replicate unavailable
      if (!outputUrl) {
        const encoded = encodeURIComponent(prompt);
        const seed = Math.floor(Math.random() * 99999);
        const baseUrl = `https://image.pollinations.ai/prompt/${encoded}?width=800&height=600&seed=${seed}&nologo=true&model=flux`;
        const img2imgUrl = baseUrl + `&image=data:image/jpeg;base64,${b64}&strength=0.65`;
        outputUrl = img2imgUrl.length > 6000 ? baseUrl : img2imgUrl;

        await new Promise((res, rej) => {
          const img = new Image();
          img.onload = res;
          img.onerror = () => rej(new Error("Render failed"));
          img.src = outputUrl;
          setTimeout(() => rej(new Error("Timed out")), 45000);
        });
      }

      setRenderUrl(outputUrl);
      setStep("result");
    } catch(e) {
      setError(e.message || "Render failed");
      setStep("color");
    }
    setRendering(false);
  }

  function getColorDescription(hex) {
    // Simple color family description
    const r = parseInt(hex.slice(1,3),16);
    const g = parseInt(hex.slice(3,5),16);
    const b = parseInt(hex.slice(5,7),16);
    const brightness = (r+g+b)/3;
    if (brightness > 220) return "very light, almost white";
    if (brightness > 180) return "light";
    if (r > g+30 && r > b+30) return "warm reddish";
    if (b > r+20 && b > g+20) return "cool blue";
    if (g > r+10 && g > b+10) return "green";
    if (Math.abs(r-g)<20 && Math.abs(g-b)<20) return "neutral gray";
    return "neutral";
  }

  const SURFACES = ["exterior walls","interior walls","cabinets","front door","trim & molding","ceiling","accent wall"];

  return (
    <div style={{ position:"fixed", inset:0, background:"rgba(0,0,0,0.7)", zIndex:500,
      display:"flex", alignItems:"flex-end", justifyContent:"center" }}>
      <div style={{ background:"#fff", borderRadius:"20px 20px 0 0", width:"100%",
        maxWidth:520, maxHeight:"92vh", display:"flex", flexDirection:"column" }}>

        {/* Mask drawing overlay */}
        {paintMaskMode && photo && (
          <div style={{ position:"absolute", inset:0, zIndex:50, display:"flex", flexDirection:"column", borderRadius:"20px 20px 0 0", overflow:"hidden" }}>
            <div style={{ background:"rgba(217,119,6,0.95)", padding:"8px 12px", display:"flex", alignItems:"center", gap:8 }}>
              <div style={{ fontSize:11, fontWeight:700, color:"#fff", flex:1 }}>
                🖌️ Paint over the {surface} you want to change
              </div>
              <input type="range" min={10} max={80} value={paintMaskSize}
                onChange={e=>setPaintMaskSize(Number(e.target.value))} style={{ width:60 }} />
              <button onClick={()=>{const cv=paintMaskRef.current;if(cv){const ctx=cv.getContext("2d");ctx.fillStyle="black";ctx.fillRect(0,0,cv.width,cv.height);}}}
                style={{ background:"rgba(255,255,255,0.2)", border:"none", color:"#fff", borderRadius:6, padding:"4px 8px", fontSize:11, fontWeight:700, cursor:"pointer" }}>Clear</button>
              <button onClick={()=>setPaintMaskMode(false)}
                style={{ background:"rgba(255,255,255,0.2)", border:"none", color:"#fff", borderRadius:6, padding:"4px 8px", fontSize:11, cursor:"pointer" }}>Cancel</button>
              <button onClick={startPreciseRender} disabled={rendering}
                style={{ background:"#15803D", border:"none", color:"#fff", borderRadius:6, padding:"5px 12px", fontSize:12, fontWeight:800, cursor:"pointer" }}>✨ Apply</button>
            </div>
            <div style={{ flex:1, position:"relative", overflow:"hidden", background:"#000" }}>
              <img src={photo} alt="" style={{ position:"absolute", inset:0, width:"100%", height:"100%", objectFit:"contain" }} />
              <canvas ref={paintMaskRef} width={800} height={600}
                style={{ position:"absolute", inset:0, width:"100%", height:"100%", objectFit:"contain",
                  touchAction:"none", cursor:"crosshair", opacity:0.45, mixBlendMode:"screen" }}
                onMouseDown={e=>{paintMaskDrawing.current=true; initPaintMask(); paintOnMask(e);}}
                onMouseMove={paintOnMask} onMouseUp={()=>{ paintMaskDrawing.current=false; }}
                onTouchStart={e=>{paintMaskDrawing.current=true; initPaintMask(); paintOnMask(e);}}
                onTouchMove={paintOnMask} onTouchEnd={()=>{ paintMaskDrawing.current=false; }}
              />
            </div>
          </div>
        )}

        {/* Header */}
        <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between",
          padding:"14px 18px 10px", borderBottom:"1px solid #E5E7EB" }}>
          <div>
            <div style={{ fontSize:15, fontWeight:800, color:BRAND.navy }}>🎨 Paint Visualizer</div>
            <div style={{ fontSize:11, color:BRAND.muted, marginTop:1 }}>
              {step==="photo" && "Upload a photo to start"}
              {step==="brand" && "Choose a paint brand"}
              {step==="color" && "Pick a color"}
              {step==="render" && "Generating your render…"}
              {step==="result" && analysis}
            </div>
          </div>
          <button onClick={onClose} style={{ background:"none", border:"none",
            fontSize:24, cursor:"pointer", color:"#6B7280", padding:0 }}>×</button>
        </div>

        <div style={{ flex:1, overflowY:"auto", padding:16 }}>

          {/* STEP: photo */}
          {step==="photo" && (
            <>
              <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:12, marginBottom:14 }}>
                <button onClick={()=>cameraRef.current.click()}
                  style={{ padding:"20px 12px", border:"2px dashed #D1D5DB", borderRadius:12,
                    background:"#F9FAFB", cursor:"pointer", textAlign:"center" }}>
                  <div style={{fontSize:28,marginBottom:6}}>📷</div>
                  <div style={{fontSize:13,fontWeight:700,color:BRAND.navy}}>Take Photo</div>
                </button>
                <button onClick={()=>fileRef.current.click()}
                  style={{ padding:"20px 12px", border:"2px dashed #D1D5DB", borderRadius:12,
                    background:"#F9FAFB", cursor:"pointer", textAlign:"center" }}>
                  <div style={{fontSize:28,marginBottom:6}}>🖼️</div>
                  <div style={{fontSize:13,fontWeight:700,color:BRAND.navy}}>Upload Photo</div>
                </button>
              </div>
              <div style={{ fontSize:11, color:BRAND.muted, background:"#FEF9C3",
                border:"1px solid #FDE047", borderRadius:8, padding:"8px 10px", lineHeight:1.5 }}>
                Works best with: exterior house photos, room interiors, kitchen cabinets.
                Good lighting and a straight-on angle give the best results.
              </div>
              <input ref={cameraRef} type="file" accept="image/*" capture="environment"
                style={{display:"none"}} onChange={e=>{
                  const f=e.target.files[0]; if(!f) return;
                  const r=new FileReader(); r.onload=ev=>{setPhoto(ev.target.result);setStep("brand");}; r.readAsDataURL(f);
                }} />
              <input ref={fileRef} type="file" accept="image/*"
                style={{display:"none"}} onChange={e=>{
                  const f=e.target.files[0]; if(!f) return;
                  const r=new FileReader(); r.onload=ev=>{setPhoto(ev.target.result);setStep("brand");}; r.readAsDataURL(f);
                }} />
            </>
          )}

          {/* STEP: brand */}
          {step==="brand" && (
            <>
              {photo && <img src={photo} alt="Your photo" style={{width:"100%",maxHeight:160,objectFit:"cover",borderRadius:10,marginBottom:14}} />}
              <div style={{fontSize:13,fontWeight:700,color:BRAND.navy,marginBottom:10}}>Choose a paint brand:</div>
              {Object.keys(PAINT_BRANDS).map(b => (
                <button key={b} onClick={()=>{setBrand(b);setCollection(null);setSelectedColor(null);setStep("color");}}
                  style={{ width:"100%", padding:"14px 16px", border:"1.5px solid #E5E7EB",
                    borderRadius:12, background:"#F9FAFB", cursor:"pointer", textAlign:"left",
                    marginBottom:8, fontSize:14, fontWeight:700, color:BRAND.navy }}>
                  {b}
                </button>
              ))}
            </>
          )}

          {/* STEP: color */}
          {step==="color" && brand && (
            <>
              {photo && <img src={photo} alt="" style={{width:"100%",maxHeight:120,objectFit:"cover",borderRadius:10,marginBottom:10}} />}

              {/* Surface selector */}
              <div style={{marginBottom:12}}>
                <div style={{fontSize:12,fontWeight:700,color:BRAND.navy,marginBottom:6}}>What are you painting?</div>
                <div style={{display:"flex",flexWrap:"wrap",gap:6}}>
                  {SURFACES.map(s => (
                    <button key={s} onClick={()=>setSurface(s)}
                      style={{ padding:"5px 10px", borderRadius:99, fontSize:11, fontWeight:700,
                        cursor:"pointer", background:surface===s?BRAND.navy:BRAND.white,
                        color:surface===s?BRAND.white:BRAND.navy,
                        border:"1.5px solid "+(surface===s?BRAND.navy:BRAND.border) }}>
                      {s}
                    </button>
                  ))}
                </div>
              </div>

              {/* Collection tabs */}
              <div style={{display:"flex",gap:6,flexWrap:"wrap",marginBottom:10}}>
                {Object.keys(PAINT_BRANDS[brand].collections).map(col => (
                  <button key={col} onClick={()=>setCollection(col)}
                    style={{ padding:"5px 10px", borderRadius:99, fontSize:11, fontWeight:700,
                      cursor:"pointer", background:collection===col?"#D97706":"#FEF3C7",
                      color:collection===col?"#fff":"#92400E",
                      border:"1.5px solid "+(collection===col?"#D97706":"#FDE68A") }}>
                    {col}
                  </button>
                ))}
              </div>

              {/* Color swatches */}
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
                {(collection ? PAINT_BRANDS[brand].collections[collection] : Object.values(PAINT_BRANDS[brand].collections).flat()).map(color => (
                  <button key={color.num} onClick={()=>setSelectedColor(color)}
                    style={{ display:"flex", alignItems:"center", gap:10, padding:"10px 12px",
                      borderRadius:10, cursor:"pointer", textAlign:"left",
                      border:"1.5px solid "+(selectedColor?.num===color.num?"#1B3A6B":"#E5E7EB"),
                      background:selectedColor?.num===color.num?"#EFF6FF":"#fff" }}>
                    <div style={{ width:36, height:36, borderRadius:8, background:color.hex,
                      flexShrink:0, border:"1px solid rgba(0,0,0,0.1)" }} />
                    <div>
                      <div style={{fontSize:12,fontWeight:700,color:BRAND.navy,lineHeight:1.2}}>{color.name}</div>
                      <div style={{fontSize:10,color:BRAND.muted}}>{color.num}</div>
                    </div>
                    {selectedColor?.num===color.num && <div style={{marginLeft:"auto",color:BRAND.navy,fontSize:14}}>✓</div>}
                  </button>
                ))}
              </div>
            </>
          )}

          {/* STEP: rendering */}
          {step==="render" && (
            <div style={{textAlign:"center",padding:"32px 0"}}>
              {photo && <img src={photo} alt="" style={{width:"100%",maxHeight:160,objectFit:"cover",borderRadius:10,marginBottom:16,opacity:0.5}} />}
              <div style={{fontSize:28,marginBottom:8}}>🎨</div>
              <div style={{fontSize:14,fontWeight:700,color:BRAND.navy}}>Applying {selectedColor?.name}…</div>
              <div style={{fontSize:12,color:BRAND.muted,marginTop:4}}>AI is rendering your color. This takes 10–20 seconds.</div>
              {error && <div style={{marginTop:12,color:"#DC2626",fontSize:12}}>⚠️ {error}</div>}
            </div>
          )}

          {/* STEP: result */}
          {step==="result" && renderUrl && (
            <>
              {selectedColor && (
                <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:12,
                  padding:"10px 12px", background:"#F9FAFB", borderRadius:10 }}>
                  <div style={{ width:36, height:36, borderRadius:8, background:selectedColor.hex,
                    flexShrink:0, border:"1px solid rgba(0,0,0,0.1)" }} />
                  <div>
                    <div style={{fontSize:13,fontWeight:800,color:BRAND.navy}}>{brand} · {selectedColor.name}</div>
                    <div style={{fontSize:11,color:BRAND.muted}}>{selectedColor.num} · {surface}</div>
                  </div>
                </div>
              )}
              <div style={{fontSize:11,fontWeight:700,color:BRAND.muted,marginBottom:4}}>ORIGINAL</div>
              <img src={photo} alt="Before" style={{width:"100%",maxHeight:200,objectFit:"cover",borderRadius:10,marginBottom:10}} />
              <div style={{fontSize:11,fontWeight:700,color:BRAND.navy,marginBottom:4}}>✨ WITH {selectedColor?.name?.toUpperCase()}</div>
              <img src={renderUrl} alt="Rendered" style={{width:"100%",maxHeight:200,objectFit:"cover",borderRadius:10,marginBottom:10}} />
              <button onClick={()=>setStep("color")}
                style={{width:"100%",padding:11,border:"1.5px solid #D1D9E8",borderRadius:11,
                  background:"#fff",fontSize:13,fontWeight:700,color:BRAND.muted,cursor:"pointer",marginBottom:8}}>
                Try Another Color
              </button>
            </>
          )}
        </div>

        {/* Footer */}
        {(step==="color"||step==="brand") && selectedColor && (
          <div style={{padding:"10px 16px",borderTop:"1px solid #E5E7EB",background:"#FAFAFA"}}>
            <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:8}}>
              <div style={{width:28,height:28,borderRadius:6,background:selectedColor.hex,flexShrink:0,border:"1px solid rgba(0,0,0,0.1)"}} />
              <div style={{fontSize:12,fontWeight:700,color:BRAND.navy}}>{selectedColor.name} · {selectedColor.num}</div>
            </div>
            <div style={{ display:"flex", gap:8 }}>
              <button onClick={()=>{ setPaintMaskMode(true); setTimeout(initPaintMask, 100); }}
                style={{ flex:1, padding:11, border:"1.5px solid #D97706", borderRadius:11,
                  background:"#FFFBEB", color:"#D97706", fontSize:13, fontWeight:800, cursor:"pointer" }}>
                🎯 Precise
              </button>
              <button onClick={startRender}
                style={{ flex:2, padding:12, border:"none", borderRadius:11,
                  background:BRAND.navy, color:"#fff", fontSize:13, fontWeight:800, cursor:"pointer" }}>
                ✨ Render
              </button>
            </div>
          </div>
        )}
        {step==="photo" && (
          <div style={{padding:"10px 16px",borderTop:"1px solid #E5E7EB"}}>
            <div style={{fontSize:11,color:BRAND.muted,textAlign:"center"}}>
              Supports: exterior, interior, cabinets, doors, trim
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

