// ─── Change Password Modal — accessible to any signed-in user ────────────────
function ChangePasswordModal({ user, onClose }) {
  const [current, setCurrent] = useState("");
  const [next, setNext] = useState("");
  const [confirm, setConfirm] = useState("");
  const [error, setError] = useState("");
  const [success, setSuccess] = useState(false);
  const [loading, setLoading] = useState(false);

  async function submit() {
    setError("");
    if (!current) { setError("Enter your current password."); return; }
    if (next.length < 6) { setError("New password must be at least 6 characters."); return; }
    if (next !== confirm) { setError("New passwords don't match."); return; }
    setLoading(true);
    try {
      const result = await verifyPassword(user.id, current);
      if (!result.ok) { setError("Current password is incorrect."); setLoading(false); return; }
      await setUserPassword(user.id, next, false);
      setSuccess(true);
      setTimeout(onClose, 1800);
    } catch {
      setError("Could not update password. Try again.");
    }
    setLoading(false);
  }

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.55)", zIndex: 260, display: "flex", alignItems: "center", justifyContent: "center", padding: 20 }} onClick={onClose}>
      <div onClick={e => e.stopPropagation()} style={{ background: BRAND.white, borderRadius: 16, width: "100%", maxWidth: 360, padding: 22 }}>
        {success ? (
          <div style={{ textAlign: "center", padding: "20px 0" }}>
            <div style={{ fontSize: 40, marginBottom: 10 }}>✅</div>
            <div style={{ fontSize: 16, fontWeight: 700, color: BRAND.navy }}>Password updated!</div>
          </div>
        ) : (
          <>
            <div style={{ fontSize: 16, fontWeight: 800, color: BRAND.navy, marginBottom: 16 }}>Change Password</div>
            <label style={S.lbl}>Current Password</label>
            <input style={S.input} type="password" value={current} onChange={e => { setCurrent(e.target.value); setError(""); }} autoFocus />
            <div style={{ marginTop: 10 }}>
              <label style={S.lbl}>New Password</label>
              <input style={S.input} type="password" placeholder="At least 6 characters" value={next} onChange={e => { setNext(e.target.value); setError(""); }} />
            </div>
            <div style={{ marginTop: 10 }}>
              <label style={S.lbl}>Confirm New Password</label>
              <input style={S.input} type="password" value={confirm} onChange={e => { setConfirm(e.target.value); setError(""); }} onKeyDown={e => e.key === "Enter" && submit()} />
            </div>
            {error && <div style={{ fontSize: 12, color: "#DC2626", marginTop: 8 }}>{error}</div>}
            <div style={{ display: "flex", gap: 8, marginTop: 16 }}>
              <button onClick={onClose} style={{ ...S.btn("ghost"), flex: 1, marginTop: 0 }}>Cancel</button>
              <button onClick={submit} disabled={loading} style={{ ...S.btn("primary"), flex: 1, marginTop: 0, opacity: loading ? 0.6 : 1 }}>
                {loading ? "Saving…" : "Update Password"}
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

// ─── Company Info ─────────────────────────────────────────────────────────────
// Admin-only tab holding official business identifiers — license number, UBI,
// TIN/EIN — plus a few other details worth having in one place. Stored as a
// single row in Supabase; visible and editable only to Brandon, Erik, and Matt.
async function fetchCompanyInfo() {
  const rows = await sbFetch("company_info?id=eq.MAIN");
  const row = (rows && rows[0]) || null;
  if (!row) return null;
  return { ...row, social_links: row.social_links ? (typeof row.social_links === "string" ? JSON.parse(row.social_links) : row.social_links) : [] };
}
async function saveCompanyInfo(info) {
  const row = { id: "MAIN", ...info, social_links: JSON.stringify(info.social_links || []), updated_at: new Date().toISOString() };
  const existing = await sbFetch("company_info?id=eq.MAIN");
  if (existing && existing.length) {
    await sbFetch("company_info?id=eq.MAIN", { method: "PATCH", body: JSON.stringify(row) });
  } else {
    await sbFetch("company_info", { method: "POST", body: JSON.stringify(row) });
  }
}

